UPDATE T_USER
USER_NAME = #{userName}, EMP_NO = #{empNo}, USER_GROUP_NO = #{userGroupNo}, USER_TYPE_CD = #{userTypeCd}, EMAIL = #{email}, PHONE_NO = #{phoneNo}, CELL_PHONE_NO = #{cellPhoneNo}, DEPT_CD = #{deptCd}, DEPT_NAME = #{deptName}, BRANCH_CD = #{branchCd}, USER_POSITION = #{userPosition}, USE_YN = #{useYn}, INFO_CHG_DT = SYSTIMESTAMP, UPD_DT = SYSTIMESTAMP, UPD_ID = #{updId}
WHERE USER_ID = #{userId}

UPDATE T_USER
   SET LOCK_YN = 'N', LOGIN_FAIL_CNT = 0, UPD_DT = SYSTIMESTAMP
 WHERE USER_ID = #{userId}

UPDATE T_USER
   SET LOGIN_FLAG = 'N'
 WHERE USER_ID = #{userId}
